using Microsoft.AspNetCore.Authorization;
using System.Security.Claims;

// The requirement — describes what must be true
public class MinimumAgeRequirement : IAuthorizationRequirement
{
    public int MinimumAge { get; }
    public MinimumAgeRequirement(int minimumAge) => MinimumAge = minimumAge;
}

// The handler — evaluates the requirement against the current user
public class MinimumAgeHandler : AuthorizationHandler<MinimumAgeRequirement>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        MinimumAgeRequirement requirement)
    {
        // Look for the date of birth claim
        var dobClaim = context.User.FindFirst(c => c.Type == ClaimTypes.DateOfBirth);
        if (dobClaim == null)
        {
            return Task.CompletedTask; // no DOB claim — requirement not met
        }

        if (DateTime.TryParse(dobClaim.Value, out var dateOfBirth))
        {
            var age = DateTime.Today.Year - dateOfBirth.Year;
            if (age >= requirement.MinimumAge)
            {
                context.Succeed(requirement); // mark requirement as satisfied
            }
        }

        return Task.CompletedTask;
    }
}

builder.Services.AddScoped<IAuthorizationHandler, MinimumAgeHandler>();

builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("MustBeAdult", policy =>
        policy.Requirements.Add(new MinimumAgeRequirement(21)));
});

