[Authorize(Policy = "MustBeAdult")]
public IActionResult PurchaseAlcohol() => View();

public class BlogPost
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string AuthorId { get; set; } = string.Empty;
}

public class BlogOperations
{
    private readonly IAuthorizationService _authService;

    public BlogOperations(IAuthorizationService authService)
    {
        _authService = authService;
    }

    public async Task<bool> CanEditPostAsync(ClaimsPrincipal user, BlogPost post)
    {
        var result = await _authService.AuthorizeAsync(user, post, "EditPost");
        return result.Succeeded;
    }
}

// Handler for the EditPost resource requirement
public class EditPostHandler : AuthorizationHandler<OperationAuthorizationRequirement, BlogPost>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        OperationAuthorizationRequirement requirement,
        BlogPost post)
    {
        if (context.User.IsInRole("Admin"))
        {
            context.Succeed(requirement);
            return Task.CompletedTask;
        }

        if (context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value == post.AuthorId)
        {
            context.Succeed(requirement);
        }

        return Task.CompletedTask;
    }
}
